entries.content:
[PAWN PROFILES — SCRIBAN TEMPLATE]

{{~ capture nl ~}}
{{~ "" ~}}
{{~ end ~}}

{{ for p in pawns }}
# PROFILE: {{ p.name }}
Full Name: {{ p.fullname }}
Gender: {{ p.gender }}
Age: {{ p.age }}
Faction: {{ p.faction }}
{{~ 
  profile_text = p.profile | StripFormattingTags | string.replace "Memory:" "Current Mood Modifiers:" 
~}}
{{- for line in (profile_text | string.split nl | array.offset 2) }}
{{ line }}
{{- end }}

# {{ p.name }}'s Current Activity:
{{ p.job | string.capitalize | StripFormattingTags }}

# {{ p.name }}'s Inventory:
{{~ if p.inventory.innerContainer.Count > 0 ~}}
{{- for line in p.inventory.innerContainer -}}
{{ line.LabelCap | StripFormattingTags }}
{{ end -}}
{{~ else ~}}
- (no items held)
{{~ end ~}}

# {{ p.name }}'s Needs:
Mood: {{ p.needs.mood.MoodString }}
{{ for need in p.needs.AllNeeds | array.offset 1 -}}{{- if need.CurCategory | string.size > 0 -}}{{ need.Def }}: {{ need.CurCategory }}
{{ end }}{{ end }}

# {{ p.name }}'s Status & Eligibility
IsColonist: {{ p.IsColonist }}
IsBaby: {{ IsBaby p }}
IsVisitor: {{ IsVisitor p }}
IsEnemy: {{ IsEnemy p }}
IsSlave: {{ p.IsSlave }}
IsPrisoner: {{ p.IsPrisoner }}
InCombat: {{ IsInCombat p }}
InDanger: {{ IsInDanger p }}
CanTalk: {{ IsTalkEligible p }}

## {{ p.name }}'s PSYCHOLOGICAL PROFILE (HIDDEN — DIRECTS ALL OUTPUT):
{{~ 
  # Safe access: check parent object first, then fields
  if p.psychProfile != null
    attachment = p.psychProfile.attachment
    defense_primary = p.psychProfile.defensePrimary
    defense_secondary = p.psychProfile.defenseSecondary
    schemas = p.psychProfile.schemas
    needs = p.psychProfile.needs
    moral = p.psychProfile.moralCompass
  else
    attachment = "Secure"
    defense_primary = "Repression"
    defense_secondary = "Humor"
    schemas = ["Emotional Deprivation", "Defectiveness/Shame"]
    needs = ["Safety", "Connection", "Autonomy"]
    moral = "Loyalty vs Universality: Kin-first"
  end
~}}
Attachment: {{ attachment }}
Primary Defense: {{ defense_primary }} | Secondary: {{ defense_secondary }}
Core Schemas: {{ schemas | array.join ", " }}
Core Needs: {{ needs | array.join ", " }}
Moral Compass: {{ moral }}

## {{ p.name }}'s Recent Memories & Perspective — REFERENCE ONLY:

# Internal Perspective
{{- for line in (StripFormattingTags p.et_thoughts | string.split nl | array.offset 1) }}
{{ line }}
{{- end }}

# Chronological Events
{{ p.memory }}

# {{ p.name }}'s Location & Surroundings
Location: {{ p.location }}
Location Beauty: {{ p.beauty }}
Location Terrain: {{ p.terrain }}
Location Cleanliness: {{ p.cleanliness }}
Things Around {{ p.name }}:
{{- for line in p.surroundings | string.split nl }}
- {{ line }}
{{- end }}
{{ end -}}

[COLONY STATUS — THEMATIC WEIGHTS]

INSTRUCTION: Treat as environmental pressure and narrative fuel.

- CONCEPTUAL TRANSLATION: Separate "System Labels" from "Narrative Nouns."
  * MECHANICAL LABELS (FORBIDDEN in dialogue): Raid, Quest, Manhunter, Cold Snap, Toxic Fallout, Mental Break, Social Fight.
  * NARRATIVE NOUNS (ALLOWED): Specific persons ("Idris"), factions, locations — the "Villains" and "Vows" of the story.

- SENSORY RECONSTRUCTION: If threat/condition lacks personal name → describe PHYSICAL IMPACT only.
  * What pawn sees, hears, feels, fears: sky state, enemy sound, cold pain.

- VOW PROTOCOL: Active quests = social/moral obligations.
  * Reference OBJECTIVE (person to save, beast to slay, debt to pay). NEVER quest title.

[THREATS]
{{ if eventplus_threats != "" -}}
{{ eventplus_threats }}
{{ else }}
No active threats.
{{ end -}}

[MAP CONDITIONS]
{{ if eventplus_conditions != "" -}}
{{ eventplus_conditions }}
{{ else }}
No active map conditions.
{{ end -}}

[ACTIVE QUESTS]
{{ if eventplus_quests != "" -}}
{{ eventplus_quests }}
{{ else }}
No active quests.
{{ end -}}

{{- if events && events != "" -}}
[Recent Events]
(Recent colony incidents; let them naturally shape mood, tone, or thoughts if still relevant, never force):
{{ events }}
{{- end -}}

[SCENE CONTEXT]

{{~ capture nl ~}}
{{ end ~}}

{{~ 
  if ctx.talk_type == "Thought"
    medium = "Thought"
  else
    medium = "Chat"
  end
  lines = ctx.DialogueType | string.split nl
  intent = lines | array.first | string.strip
  topic = lines | array.offset 1 | array.join "; " | string.strip
~}}

## CONVERSATION TRIGGER
- Pawn Roster: [{{ pawns | array.join ", " }}]
- Initiating Pawn: {{ pawn }}
- Intended Recipient: {{ recipient }}
- Medium: {{ medium }}
- Intent: {{ intent }}
- Conversation Topic: {{ topic }}

# WORLD STATE
Time: {{ hour }}h | Date: {{ quadrum }} {{ day }}, {{ year }}
Season: {{ season }} | Weather: {{ map.weather }} | Biome: {{ map.Biome.label }}

[IMMEDIATE EXECUTION PROTOCOL]
1. BREVITY CEILING (CRITICAL): Turns MUST NOT exceed 40 words. Exceeding = CRITICAL FAILURE.
2. TURN-LOCK: Target → Initiator sequence. No turn stealing.
3. IDENTITY OVER THEME: Every pawn filters topic through [Personality] lens. Generic agreement FORBIDDEN.
4. FLAT ARRAY LOCK: Output = EXACTLY ONE [ ] array. Nesting [[ ]] FORBIDDEN.
5. LEXICAL FILTER: [NATURALISTIC LEXICON] + British English spelling (-our, -ise, -re).
6. ANTI-LOOP: NO copy/repeat from [Chronological Events] or [History]. All text = NOVEL.
7. DATA OUTPUT: RAW JSON ARRAY EXCLUSIVELY.

{{ prompt }}

{{ json.anchor }}
